WITH flattened_attrs AS (SELECT id, created_at, attributes, ARRAY_CONTAINS(MAP_KEYS(attributes), 'utm_source') AS has_utm_source, FORALL(items, li -> li.qty <= 5) AS all_small_qty, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text, ship_to.country AS ship_country, COALESCE(attributes['utm_source'], 'none') AS utm_source_or_default FROM carts) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, MAX(created_at) AS last_created_at, MAX(created_at) AS last_seen, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes FROM flattened_attrs GROUP BY DATE_TRUNC('HOUR', created_at) HAVING (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 > 0;
